#include "ppbng_core/frame_context_association.hpp"
#include <gtest/gtest.h>
using namespace ppbng_core;
namespace {GnssObservation pos(std::uint64_t s,std::int64_t t,double x){GnssObservation g;g.sequence=s;g.utc_nanoseconds=t;g.host_monotonic_nanoseconds=s*100U;g.latitude_degrees=x;g.longitude_degrees=1;g.altitude_meters=2;g.fix_quality=4;g.position_valid=true;return g;}RsmAttitudeSample rsm(std::uint64_t s,std::int64_t t,double x){return{s,t,x,x,0,true,true,true,false,0};}}
TEST(FrameContext, StrictlyBracketsBothDomains){FrameContextAssociator a(2000,1000,1000);ASSERT_TRUE(a.add_gnss_position(pos(1,1000,1)));ASSERT_TRUE(a.add_gnss_position(pos(2,2000,2)));ASSERT_TRUE(a.add_gnss_heading({1,1000,100,359,1,true}));ASSERT_TRUE(a.add_gnss_heading({2,2000,200,1,3,true}));ASSERT_TRUE(a.add_rsm(rsm(1,100,1)));ASSERT_TRUE(a.add_rsm(rsm(2,200,3)));auto x=a.associate({1500,150});ASSERT_TRUE(x.gnss);ASSERT_TRUE(x.rsm);ASSERT_TRUE(x.heading_deg);EXPECT_EQ(x.gnss_status,ContextAvailability::available);EXPECT_NEAR(*x.heading_deg,0,1e-9);EXPECT_NEAR(x.rsm->roll_deg,2,1e-9);}
TEST(FrameContext, WithoutPpsUsesExplicitlyDegradedHostMonotonicGnssBracket){FrameContextAssociator a(2000,1000,1000);ASSERT_TRUE(a.add_gnss_position(pos(1,1000,1)));ASSERT_TRUE(a.add_gnss_position(pos(2,2000,2)));ASSERT_TRUE(a.add_gnss_heading({1,1000,100,359,1,true}));ASSERT_TRUE(a.add_gnss_heading({2,2000,200,1,3,true}));auto x=a.associate({0,150});ASSERT_TRUE(x.gnss);ASSERT_TRUE(x.heading_deg);EXPECT_EQ(x.gnss_status,ContextAvailability::degraded);EXPECT_EQ(x.gnss->utc_nanoseconds,1500);EXPECT_NE(x.gnss_detail.find("host-monotonic"),std::string::npos);EXPECT_NE(x.gnss_detail.find("PPS unavailable"),std::string::npos);}
TEST(FrameContext, NeverExtrapolatesOrUsesStaleData){FrameContextAssociator a(100,50,50);a.add_gnss_position(pos(1,1000,1));a.add_gnss_position(pos(2,1200,2));a.add_rsm(rsm(1,100,1));a.add_rsm(rsm(2,300,3));auto x=a.associate({1100,200});EXPECT_FALSE(x.gnss);EXPECT_FALSE(x.rsm);EXPECT_EQ(x.gnss_status,ContextAvailability::unavailable);}
TEST(FrameContext, RejectsRegressionAndResetDropsHistory){FrameContextAssociator a(1000,1000,1000);EXPECT_TRUE(a.add_gnss_position(pos(1,1,1)));EXPECT_FALSE(a.add_gnss_position(pos(1,2,1)));a.reset();EXPECT_TRUE(a.add_gnss_position(pos(1,1,1)));}
